# Aplikasi Kasir Berbasis OOP Lengkap
class Kasir:
    def __init__(self, nama):
        self.nama = nama
        self.items = []
    def tambah(self, item, harga):
        self.items.append({'item': item, 'harga': harga})
    def hitung(self):
        return sum(x['harga'] for x in self.items)

k = Kasir('Snakeling Cafe')
k.tambah('Espresso', 18000)
print('Total:', k.hitung())

